{"content":"'use client';

import { Handle, Position, NodeProps } from 'reactflow';
import { NodeData } from '@/types';
import BaseNode from './BaseNode';

export default function VideoExportNode({ data, selected }: NodeProps<NodeData>) {
  const video = data.params?.value;

  return (
    <BaseNode data={data} selected={selected} color="#a855f7">
      <div className="space-y-2">
        {/* Ports */}
        <div className="flex items-center justify-between text-[11px]">
          <div className="flex items-center gap-1">
            <span className="text-white/60">输入</span>
            <span className="bg-purple-500/20 text-purple-400 border border-purple-500/30 rounded px-1.5 py-0.5 text-[10px]">VIDEO</span>
          </div>
        </div>

        {/* Preview */}
        {video ? (
          <div className="rounded overflow-hidden bg-black/30">
            <video
              src={video}
              controls
              className="w-full h-auto max-h-[200px]"
            />
          </div>
        ) : (
          <div className="h-24 flex items-center justify-center text-white/20 text-[11px] bg-black/20 rounded border border-dashed border-white/10">
            等待输入视频
          </div>
        )}

        {/* Download */}
        {video && (
          <a
            href={video}
            download
            target="_blank"
            rel="noopener noreferrer"
            className="block w-full text-center text-[11px] py-1.5 rounded bg-white/5 text-white/60 hover:bg-white/10 hover:text-white/80 transition-colors"
          >
            下载视频
          </a>
        )}
      </div>

      <Handle
        type="target"
        position={Position.Left}
        className="w-3 h-3 bg-purple-500 border-2 border-purple-300"
        style={{ left: -6 }}
      />
    </BaseNode>
  );
}
