3|import React, { useState, useRef, useEffect } from "react";
4|import BaseNode from "./BaseNode";
5|import type { NodeProps } from "@xyflow/react";
6|import type { NodeData } from "@/types/workflow";
7|import { useSettingsStore } from "@/stores/settingsStore";
8|import { useWorkflowStore } from "@/stores/workflowStore";
9|
10|// 已验证可用的图片模型
11|const IMAGE_MODELS = [
12|  "gemini-3-pro-image-preview-official",
13|  "nano_banana_2",
14|];
15|
16|export default function ImageGenNode(props: NodeProps) {
17|  const d = props.data as unknown as NodeData;
18|  const cfg = d.config as { prompt?: string; model?: string; resultUrl?: string; taskId?: string };
19|  const { imageApi } = useSettingsStore();
20|  const { updateNodeData } = useWorkflowStore();
21|
22|  const [prompt, setPrompt] = useState(cfg.prompt ?? "");
23|  const [selectedModel, setSelectedModel] = useState(cfg.model ?? IMAGE_MODELS[0]);
24|  const [previewUrl, setPreviewUrl] = useState<string | null>(cfg.resultUrl ?? null);
25|  const [error, setError] = useState<string | null>(null);
26|  const [loading, setLoading] = useState(false);
27|  const [progress, setProgress] = useState(0);
28|  const pollRef = useRef<NodeJS.Timeout | null>(null);
29|
30|  useEffect(() => {
31|    return () => { if (pollRef.current) clearInterval(pollRef.current); };
32|  }, []);
33|
34|  const pollTask = (taskId: string) => {
35|    pollRef.current = setInterval(async () => {
36|      try {
37|        const resp = await fetch(
38|          `http://localhost:8000/api/generate/task/image/${taskId}?api_url=${encodeURIComponent(imageApi.apiUrl)}&api_key=${encodeURIComponent(imageApi.apiKey)}`
39|        );
40|        if (!resp.ok) return;
41|        const data = await resp.json();
42|        setProgress(data.progress || 0);
43|
44|        if (data.status === "completed" && data.url) {
45|          clearInterval(pollRef.current!);
46|          setPreviewUrl(data.url);
47|          setLoading(false);
48|          setProgress(100);
49|          updateNodeData(props.id, {
50|            status: "success", progress: 100,
51|            config: { ...cfg, prompt, model: selectedModel, resultUrl: data.url, taskId },
52|          });
53|        } else if (data.status === "failed") {
54|          clearInterval(pollRef.current!);
55|          setError(data.error || "生成失败");
56|          setLoading(false);
57|          updateNodeData(props.id, { status: "error" });
58|        }
59|      } catch {}
60|    }, 5000);
61|  };
62|
63|  const handleGenerate = async () => {
64|    if (loading) return;
65|    if (!prompt.trim()) { setError("请输入Prompt"); return; }
66|    if (!imageApi.apiUrl || !imageApi.apiKey) { setError("请先在设置中配置API Key"); return; }
67|
68|    setError(null);
69|    setLoading(true);
70|    setProgress(0);
71|    setPreviewUrl(null);
72|    updateNodeData(props.id, { status: "running", progress: 0 });
73|
74|    try {
75|      const resp = await fetch("http://localhost:8000/api/generate/image", {
76|        method: "POST",
77|        headers: { "Content-Type": "application/json" },
78|        body: JSON.stringify({ prompt, api_url: imageApi.apiUrl, api_key: imageApi.apiKey, model: selectedModel }),
79|      });
80|
81|      if (!resp.ok) {
82|        const err = await resp.json();
83|        throw new Error(err.detail || "创建任务失败");
84|      }
85|
86|      const data = await resp.json();
87|      if (data.task_id) {
88|        pollTask(data.task_id);
89|      } else {
90|        throw new Error("未返回任务ID");
91|      }
92|    } catch (e) {
93|      setError(e instanceof Error ? e.message : "生成失败");
94|      setLoading(false);
95|      updateNodeData(props.id, { status: "error" });
96|    }
97|  };
98|
99|  return (
100|    <BaseNode {...props}>
101|      <div style={{ padding: "0 10px 8px" }}>
102|        {/* 模型选择 */}
103|        <select
104|          value={selectedModel}
105|          onChange={(e) => setSelectedModel(e.target.value)}
106|          disabled={loading}
107|          style={{
108|            width: "100%", marginBottom: 6, fontSize: 11, color: "#d0d6e0",
109|            background: "#0a0a0f", border: "1px solid rgba(255,255,255,0.12)",
110|            borderRadius: 4, padding: "4px 6px", outline: "none",
111|          }}
112|        >
113|          {IMAGE_MODELS.map(m => <option key={m} value={m}>{m}</option>)}
114|        </select>
115|
116|        {/* Prompt */}
117|        <textarea
118|          value={prompt}
119|          onChange={(e) => setPrompt(e.target.value)}
120|          placeholder="输入图片描述..."
121|          disabled={loading}
122|          onClick={(e) => e.stopPropagation()}
123|          style={{
124|            width: "100%", height: 50, fontSize: 12, color: "#e0e0e0",
125|            background: "#0a0a0f",
126|            border: `1px solid ${error ? "#ef4444" : "rgba(255,255,255,0.12)"}`,
127|            borderRadius: 4, padding: "6px 8px", resize: "none", outline: "none",
128|          }}
129|        />
130|
131|        {error && (
132|          <div style={{ marginTop: 4, padding: "4px 6px", background: "rgba(239,68,68,0.1)", borderRadius: 4, border: "1px solid rgba(239,68,68,0.3)" }}>
133|            <p style={{ fontSize: 10, color: "#ef4444", wordBreak: "break-all" }}>{error}</p>
134|          </div>
135|        )}
136|
137|        <button
138|          onClick={handleGenerate}
139|          disabled={loading}
140|          style={{
141|            width: "100%", marginTop: 6, fontSize: 12, fontWeight: 600, color: "#fff",
142|            background: loading ? "rgba(94,106,210,0.4)" : "#5e6ad2",
143|            border: "none", borderRadius: 4, padding: "6px 10px",
144|            cursor: loading ? "not-allowed" : "pointer",
145|          }}
146|        >
147|          {loading ? `生成中 ${Math.round(progress)}%` : previewUrl ? "重新生成" : "生成图片"}
148|        </button>
149|
150|        {loading && (
151|          <div style={{ marginTop: 4, height: 4, background: "rgba(255,255,255,0.08)", borderRadius: 2, overflow: "hidden" }}>
152|            <div style={{ width: `${progress}%`, height: "100%", background: "#5e6ad2", borderRadius: 2, transition: "width 0.5s" }} />
153|          </div>
154|        )}
155|
156|        {previewUrl && (
157|          <div style={{ marginTop: 6, borderRadius: 4, overflow: "hidden", border: "1px solid rgba(255,255,255,0.12)" }}>
158|            <img src={previewUrl} alt="预览" style={{ width: "100%", height: 100, objectFit: "cover", display: "block" }} />
159|          </div>
160|        )}
161|      </div>
162|    </BaseNode>
163|  );
164|}
