{"content": "1|import { create } from "zustand";
2|import type { Node, Edge, OnNodesChange, OnEdgesChange, Connection } from "@xyflow/react";
3|import { applyNodeChanges, applyEdgeChanges, addEdge } from "@xyflow/react";
4|import type { NodeData } from "@/types/workflow";
5|import { MAX_UNDO_STEPS } from "@/lib/constants";
6|import { isValidConnection } from "@/lib/validation";
7|
8|interface Snapshot {
9|  nodes: Node<NodeData>[];
10|  edges: Edge[];
11|}
12|
13|interface WorkflowState {
14|  nodes: Node<NodeData>[];
15|  edges: Edge[];
16|  selectedNodeId: string | null;
17|  propertyPanelOpen: boolean;
18|  executionPanelOpen: boolean;
19|  miniMapVisible: boolean;
20|  undoStack: Snapshot[];
21|  redoStack: Snapshot[];
22|  workflowName: string;
23|  isInitialized: boolean;
24|
25|  onNodesChange: OnNodesChange;
26|  onEdgesChange: OnEdgesChange;
27|  onConnect: (connection: Connection) => void;
28|  addNode: (node: Node<NodeData>) => void;
29|  removeNode: (nodeId: string) => void;
30|  updateNodeData: (nodeId: string, data: Partial<NodeData>) => void;
31|  selectNode: (nodeId: string | null) => void;
32|  togglePropertyPanel: () => void;
33|  toggleExecutionPanel: () => void;
34|  toggleMiniMap: () => void;
35|  undo: () => void;
36|  redo: () => void;
37|  saveSnapshot: () => void;
38|  clearWorkflow: () => void;
39|  loadWorkflow: (nodes: Node<NodeData>[], edges: Edge[], name?: string) => void;
40|  initializeWorkflow: () => void;
41|}
42|
43|const STORAGE_KEY = "antoken-workflow";
44|
45|function saveToStorage(state: Pick<WorkflowState, "nodes" | "edges" | "workflowName">) {
46|  try {
47|    localStorage.setItem(STORAGE_KEY, JSON.stringify({
48|      nodes: state.nodes,
49|      edges: state.edges,
50|      workflowName: state.workflowName,
51|    }));
52|  } catch { /* quota exceeded */ }
53|}
54|
55|function loadFromStorage(): { nodes: Node<NodeData>[]; edges: Edge[]; workflowName: string } | null {
56|  try {
57|    const raw = localStorage.getItem(STORAGE_KEY);
58|    if (!raw) return null;
59|    return JSON.parse(raw);
60|  } catch {
61|    return null;
62|  }
63|}
64|
65|export const useWorkflowStore = create<WorkflowState>((set, get) => ({
66|  nodes: [],
67|  edges: [],
68|  selectedNodeId: null,
69|  propertyPanelOpen: false,
70|  executionPanelOpen: false,
71|  miniMapVisible: true,
72|  undoStack: [],
73|  redoStack: [],
74|  workflowName: "Untitled Workflow",
75|  isInitialized: false,
76|
77|  initializeWorkflow: () => {
78|    if (get().isInitialized) return;
79|    const saved = loadFromStorage();
80|    if (saved && saved.nodes.length > 0) {
81|      set({
82|        nodes: saved.nodes,
83|        edges: saved.edges,
84|        workflowName: saved.workflowName,
85|        isInitialized: true,
86|      });
87|    } else {
88|      set({ isInitialized: true });
89|    }
90|  },
91|
92|  onNodesChange: (changes) => {
93|    set((s) => {
94|      const updated = applyNodeChanges(changes, s.nodes) as Node<NodeData>[];
95|      saveToStorage({ nodes: updated, edges: s.edges, workflowName: s.workflowName });
96|      return { nodes: updated };
97|    });
98|  },
99|
100|  onEdgesChange: (changes) => {
101|    set((s) => {
102|      const updated = applyEdgeChanges(changes, s.edges);
103|      saveToStorage({ nodes: s.nodes, edges: updated, workflowName: s.workflowName });
104|      return { edges: updated };
105|    });
106|  },
107|
108|  onConnect: (connection) => {
109|    if (connection.source === connection.target) return;
110|
111|    const sourceNode = get().nodes.find((n) => n.id === connection.source);
112|    const targetNode = get().nodes.find((n) => n.id === connection.target);
113|
114|    if (sourceNode && targetNode) {
115|      const sourceOutput = (sourceNode.data as NodeData).outputs.find(
116|        (o) => o.id === connection.sourceHandle
117|      );
118|      const targetInput = (targetNode.data as NodeData).inputs.find(
119|        (i) => i.id === connection.targetHandle
120|      );
121|
122|      if (sourceOutput && targetInput && !isValidConnection(sourceOutput.type, targetInput.type)) {
123|        console.warn("Type mismatch:", sourceOutput.type, "->", targetInput.type, "(connection allowed)");
124|      }
125|    }
126|
127|    get().saveSnapshot();
128|    set((s) => {
129|      const updated = addEdge(
130|        {
131|          ...connection,
132|          animated: true,
133|          style: { stroke: "#5e6ad2", strokeWidth: 2 },
134|          type: "smoothstep",
135|        },
136|        s.edges
137|      );
138|      saveToStorage({ nodes: s.nodes, edges: updated, workflowName: s.workflowName });
139|      return { edges: updated };
140|    });
141|  },
142|
143|  addNode: (node) => {
144|    get().saveSnapshot();
145|    set((s) => {
146|      const updated = [...s.nodes, node];
147|      saveToStorage({ nodes: updated, edges: s.edges, workflowName: s.workflowName });
148|      return { nodes: updated };
149|    });
150|  },
151|
152|  removeNode: (nodeId) => {
153|    get().saveSnapshot();
154|    set((s) => {
155|      const nodes = s.nodes.filter((n) => n.id !== nodeId);
156|      const edges = s.edges.filter((e) => e.source !== nodeId && e.target !== nodeId);
157|      saveToStorage({ nodes, edges, workflowName: s.workflowName });
158|      return {
159|        nodes,
160|        edges,
161|        selectedNodeId: s.selectedNodeId === nodeId ? null : s.selectedNodeId,
162|        propertyPanelOpen: s.selectedNodeId === nodeId ? false : s.propertyPanelOpen,
163|      };
164|    });
165|  },
166|
167|  updateNodeData: (nodeId, data) => {
168|    set((s) => {
169|      const nodes = s.nodes.map((n) =>
170|        n.id === nodeId ? { ...n, data: { ...n.data, ...data } } : n
171|      ) as Node<NodeData>[];
172|      saveToStorage({ nodes, edges: s.edges, workflowName: s.workflowName });
173|      return { nodes };
174|    });
175|  },
176|
177|  selectNode: (nodeId) => {
178|    set({ selectedNodeId: nodeId, propertyPanelOpen: nodeId !== null });
179|  },
180|
181|  togglePropertyPanel: () => set((s) => ({ propertyPanelOpen: !s.propertyPanelOpen })),
182|  toggleExecutionPanel: () => set((s) => ({ executionPanelOpen: !s.executionPanelOpen })),
183|  toggleMiniMap: () => set((s) => ({ miniMapVisible: !s.miniMapVisible })),
184|
185|  saveSnapshot: () => {
186|    set((s) => {
187|      const snap: Snapshot = { nodes: s.nodes, edges: s.edges };
188|      const stack = [...s.undoStack, snap].slice(-MAX_UNDO_STEPS);
189|      return { undoStack: stack, redoStack: [] };
190|    });
191|  },
192|
193|  undo: () => {
194|    const { undoStack, nodes, edges } = get();
195|    if (undoStack.length === 0) return;
196|    const prev = undoStack[undoStack.length - 1];
197|    set((s) => ({
198|      nodes: prev.nodes,
199|      edges: prev.edges,
200|      undoStack: s.undoStack.slice(0, -1),
201|      redoStack: [...s.redoStack, { nodes, edges }],
202|    }));
203|    saveToStorage({ nodes: prev.nodes, edges: prev.edges, workflowName: get().workflowName });
204|  },
205|
206|  redo: () => {
207|    const { redoStack, nodes, edges } = get();
208|    if (redoStack.length === 0) return;
209|    const next = redoStack[redoStack.length - 1];
210|    set((s) => ({
211|      nodes: next.nodes,
212|      edges: next.edges,
213|      redoStack: s.redoStack.slice(0, -1),
214|      undoStack: [...s.undoStack, { nodes, edges }],
215|    }));
216|    saveToStorage({ nodes: next.nodes, edges: next.edges, workflowName: get().workflowName });
217|  },
218|
219|  clearWorkflow: () => {
220|    get().saveSnapshot();
221|    set({ nodes: [], edges: [], selectedNodeId: null, propertyPanelOpen: false });
222|    localStorage.removeItem(STORAGE_KEY);
223|  },
224|
225|  loadWorkflow: (nodes, edges, name) => {
226|    get().saveSnapshot();
227|    set({ nodes, edges, workflowName: name ?? "Untitled Workflow", selectedNodeId: null });
228|    saveToStorage({ nodes, edges, workflowName: name ?? "Untitled Workflow" });
229|  },
230|}));
