import { Handle, Position, NodeProps } from 'reactflow';
import { NodeData } from '@/types';
import BaseNode from './BaseNode';
import { useWorkflowStore } from '@/stores/workflowStore';

export default function ImageExportNode({ id, data, selected }: NodeProps<NodeData>) {
  const { nodes, edges } = useWorkflowStore();

  // 从连接的上游节点获取图片URL
  const incomingEdge = edges.find(e => e.target === id);
  const sourceNode = incomingEdge ? nodes.find(n => n.id === incomingEdge.source) : null;
  const sourceConfig = sourceNode?.data?.config as Record<string, unknown> | undefined;
  const imgUrl = (sourceConfig?.resultUrl as string) || null;

  return (
    <BaseNode data={data} selected={selected} color="#3b82f6">
      <div className="space-y-2">
        {/* Ports */}
        <div className="flex items-center justify-between text-[11px]">
          <div className="flex items-center gap-1">
            <span className="text-white/60">输入</span>
            <span className="bg-blue-500/20 text-blue-400 border border-blue-500/30 rounded px-1.5 py-0.5 text-[10px]">IMAGE</span>
          </div>
        </div>

        {/* Preview */}
        {imgUrl ? (
          <div className="rounded overflow-hidden bg-black/30">
            <img
              src={imgUrl}
              alt="输出图片"
              className="w-full h-auto max-h-[200px] object-contain"
            />
          </div>
        ) : (
          <div className="h-24 flex items-center justify-center text-white/20 text-[11px] bg-black/20 rounded border border-dashed border-white/10">
            {incomingEdge ? '等待上游生成...' : '连接图片生成节点'}
          </div>
        )}

        {/* Download */}
        {imgUrl && (
          <a
            href={imgUrl}
            download
            target="_blank"
            rel="noopener noreferrer"
            className="block w-full text-center text-[11px] py-1.5 rounded bg-white/5 text-white/60 hover:bg-white/10 hover:text-white/80 transition-colors"
          >
            下载图片
          </a>
        )}
      </div>

      <Handle
        type="target"
        position={Position.Left}
        className="w-3 h-3 bg-blue-500 border-2 border-blue-300"
        style={{ left: -6 }}
      />
    </BaseNode>
  );
}
