{"content":"'use client';

import React from 'react';
import BaseNode from './BaseNode';
import type { NodeProps } from '@xyflow/react';
import type { NodeData } from '@/types/workflow';
import { Handle, Position } from 'reactflow';
import { useWorkflowStore } from '@/stores/workflowStore';

export default function VideoCompositeNode({ id, data, selected }: NodeProps) {
  const d = data as unknown as NodeData;
  const cfg = d.config as { mode?: string; duration?: number; position?: string };
  const { nodes, edges } = useWorkflowStore();

  // 从连接的上游节点获取图片和视频
  const incomingEdges = edges.filter(e => e.target === id);
  let imgUrl: string | null = null;
  let videoUrl: string | null = null;

  for (const edge of incomingEdges) {
    const sourceNode = nodes.find(n => n.id === edge.source);
    if (!sourceNode) continue;
    const sourceConfig = sourceNode.data?.config as Record<string, unknown> | undefined;
    const resultUrl = sourceConfig?.resultUrl as string | undefined;
    if (!resultUrl) continue;

    // 根据handle类型判断
    if (edge.targetHandle === 'image') {
      imgUrl = resultUrl;
    } else if (edge.targetHandle === 'video') {
      videoUrl = resultUrl;
    }
  }

  return (
    <BaseNode data={d} selected={selected} color="#3b82f6">
      <div style={{ padding: '0 10px 8px' }}>
        {/* 预览区 */}
        <div style={{ display: 'flex', gap: 4, marginBottom: 6 }}>
          {/* 图片预览 */}
          <div style={{ flex: 1, borderRadius: 4, overflow: 'hidden', background: '#0a0a0f', border: '1px solid rgba(255,255,255,0.08)', minHeight: 60, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {imgUrl ? (
              <img src={imgUrl} alt="图片输入" style={{ width: '100%', height: 60, objectFit: 'cover' }} />
            ) : (
              <span style={{ fontSize: 9, color: '#3a3d45' }}>图片</span>
            )}
          </div>
          {/* 视频预览 */}
          <div style={{ flex: 1, borderRadius: 4, overflow: 'hidden', background: '#0a0a0f', border: '1px solid rgba(255,255,255,0.08)', minHeight: 60, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {videoUrl ? (
              <video src={videoUrl} muted style={{ width: '100%', height: 60, objectFit: 'cover' }} />
            ) : (
              <span style={{ fontSize: 9, color: '#3a3d45' }}>视频</span>
            )}
          </div>
        </div>

        {/* 合成模式 */}
        <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 9, padding: '1px 6px', borderRadius: 9999, color: '#f59e0b', background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.2)' }}>
            {cfg.mode ?? 'overlay'}
          </span>
          <span style={{ fontSize: 9, padding: '1px 6px', borderRadius: 9999, color: '#8a8f98', background: 'rgba(138,143,152,0.1)', border: '1px solid rgba(138,143,152,0.2)' }}>
            {cfg.position ?? 'center'}
          </span>
        </div>

        {/* 状态 */}
        {imgUrl && videoUrl && (
          <div style={{ marginTop: 4, fontSize: 9, color: '#22c55e' }}>
            素材就绪，可合成
          </div>
        )}
      </div>

      <Handle
        type="target"
        position={Position.Left}
        id="image"
        className="w-3 h-3 bg-blue-500 border-2 border-blue-300"
        style={{ left: -6, top: '40%' }}
      />
      <Handle
        type="target"
        position={Position.Left}
        id="video"
        className="w-3 h-3 bg-purple-500 border-2 border-purple-300"
        style={{ left: -6, top: '60%' }}
      />
      <Handle
        type="source"
        position={Position.Right}
        id="video"
        className="w-3 h-3 bg-purple-500 border-2 border-purple-300"
        style={{ right: -6 }}
      />
    </BaseNode>
  );
}
