{"content":"'use client';

import { Handle, Position } from '@xyflow/react';
import type { NodeProps } from '@xyflow/react';
import type { NodeData } from '@/types';
import BaseNode from './BaseNode';
import { useWorkflowStore } from '@/stores/workflowStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useState, useRef, useEffect } from 'react';

export default function ImageExportNode({ id, data, selected }: NodeProps<NodeData>) {
  const { nodes, edges, updateNodeData } = useWorkflowStore();
  const { imageApi } = useSettingsStore();

  const cfg = data.config as { prompt?: string; resultUrl?: string; taskId?: string };
  const [prompt, setPrompt] = useState(cfg.prompt ?? '');
  const [resultUrl, setResultUrl] = useState<string | null>(cfg.resultUrl ?? null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const pollRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => () => { if (pollRef.current) clearInterval(pollRef.current); }, []);

  // 从上游获取图片
  const incomingEdge = edges.find(e => e.target === id);
  const sourceNode = incomingEdge ? nodes.find(n => n.id === incomingEdge.source) : null;
  const sourceConfig = sourceNode?.data?.config as Record<string, unknown> | undefined;
  const inputUrl = (sourceConfig?.resultUrl as string) || null;

  const pollTask = (taskId: string) => {
    pollRef.current = setInterval(async () => {
      try {
        const resp = await fetch(
          `http://localhost:8000/api/generate/task/image/${taskId}?api_url=${encodeURIComponent(imageApi.apiUrl)}&api_key=${encodeURIComponent(imageApi.apiKey)}`
        );
        if (!resp.ok) return;
        const d = await resp.json();
        setProgress(d.progress || 0);
        if (d.status === 'completed' && d.url) {
          clearInterval(pollRef.current!);
          setResultUrl(d.url);
          setLoading(false);
          setProgress(100);
          updateNodeData(id, { config: { ...cfg, prompt, resultUrl: d.url, taskId } });
        } else if (d.status === 'failed') {
          clearInterval(pollRef.current!);
          setError(d.error || '合成失败');
          setLoading(false);
        }
      } catch {}
    }, 5000);
  };

  const handleCompose = async () => {
    if (loading) return;
    if (!inputUrl) { setError('请先连接图片生成节点'); return; }
    if (!prompt.trim()) { setError('请输入合成提示词'); return; }
    if (!imageApi.apiUrl || !imageApi.apiKey) { setError('请先配置API'); return; }

    setError(null);
    setLoading(true);
    setProgress(0);

    try {
      // 用提示词+原图进行二次生成（图生图）
      const resp = await fetch('http://localhost:8000/api/generate/image', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt: `${prompt}\n参考图片: ${inputUrl}`,
          api_url: imageApi.apiUrl,
          api_key: imageApi.apiKey,
          model: 'gemini-3-pro-image-preview-official',
        }),
      });
      if (!resp.ok) { const e = await resp.json(); throw new Error(e.detail || '创建任务失败'); }
      const d = await resp.json();
      if (d.task_id) pollTask(d.task_id);
      else throw new Error('未返回任务ID');
    } catch (e) {
      setError(e instanceof Error ? e.message : '合成失败');
      setLoading(false);
    }
  };

  return (
    <BaseNode data={data} selected={selected} color="#3b82f6">
      <div className="space-y-2">
        <div className="flex items-center justify-between text-[11px]">
          <div className="flex items-center gap-1">
            <span className="text-white/60">输入</span>
            <span className="bg-blue-500/20 text-blue-400 border border-blue-500/30 rounded px-1.5 py-0.5 text-[10px]">IMAGE</span>
          </div>
          <div className="flex items-center gap-1">
            <span className="bg-blue-500/20 text-blue-400 border border-blue-500/30 rounded px-1.5 py-0.5 text-[10px]">IMAGE</span>
            <span className="text-white/60">输出</span>
          </div>
        </div>

        {/* 合成提示词 */}
        <textarea
          value={prompt}
          onChange={e => setPrompt(e.target.value)}
          placeholder="输入合成要求，如：把背景换成海边..."
          onClick={e => e.stopPropagation()}
          style={{
            width: '100%', height: 40, fontSize: 11, color: '#e0e0e0',
            background: '#0a0a0f', border: `1px solid ${error ? '#ef4444' : 'rgba(255,255,255,0.12)'}`,
            borderRadius: 4, padding: '4px 6px', resize: 'none', outline: 'none',
          }}
        />

        {error && (
          <div style={{ padding: '3px 6px', background: 'rgba(239,68,68,0.1)', borderRadius: 4, border: '1px solid rgba(239,68,68,0.3)' }}>
            <p style={{ fontSize: 9, color: '#ef4444', wordBreak: 'break-all' }}>{error}</p>
          </div>
        )}

        {/* 合成按钮 */}
        <button
          onClick={handleCompose}
          disabled={loading || !inputUrl}
          style={{
            width: '100%', fontSize: 11, fontWeight: 600, color: '#fff',
            background: loading ? 'rgba(94,106,210,0.4)' : '#5e6ad2',
            border: 'none', borderRadius: 4, padding: '5px 8px',
            cursor: loading || !inputUrl ? 'not-allowed' : 'pointer',
          }}
        >
          {loading ? `合成中 ${Math.round(progress)}%` : resultUrl ? '重新合成' : '开始合成'}
        </button>

        {loading && (
          <div style={{ height: 3, background: 'rgba(255,255,255,0.08)', borderRadius: 2, overflow: 'hidden' }}>
            <div style={{ width: `${progress}%`, height: '100%', background: '#5e6ad2', borderRadius: 2, transition: 'width 0.5s' }} />
          </div>
        )}

        {/* 输出预览 */}
        {resultUrl ? (
          <div className="rounded overflow-hidden bg-black/30">
            <img src={resultUrl} alt="合成结果" className="w-full h-auto max-h-[150px] object-contain" />
          </div>
        ) : inputUrl ? (
          <div className="rounded overflow-hidden bg-black/30 opacity-50">
            <img src={inputUrl} alt="输入素材" className="w-full h-auto max-h-[100px] object-contain" />
          </div>
        ) : null}

        {resultUrl && (
          <a href={resultUrl} download target="_blank" rel="noopener noreferrer"
            className="block w-full text-center text-[11px] py-1.5 rounded bg-white/5 text-white/60 hover:bg-white/10 hover:text-white/80 transition-colors">
            下载图片
          </a>
        )}
      </div>

      <Handle type="target" position={Position.Left}
        className="w-3 h-3 bg-blue-500 border-2 border-blue-300" style={{ left: -6 }} />
      <Handle type="source" position={Position.Right}
        className="w-3 h-3 bg-blue-500 border-2 border-blue-300" style={{ right: -6 }} />
    </BaseNode>
  );
}
