import { useState, useRef, useEffect } from 'react';

export default function VideoExportNode({ id, data, selected }: NodeProps<NodeData>) {
  const { nodes, edges, updateNodeData } = useWorkflowStore();
  const { videoApi } = useSettingsStore();

  const cfg = data.config as { prompt?: string; resultUrl?: string; taskId?: string };
