{"content":"'use client';

import React, { useState, useRef, useEffect } from 'react';
import BaseNode from './BaseNode';
import type { NodeProps } from '@xyflow/react';
import type { NodeData } from '@/types/workflow';
import { Handle, Position } from '@xyflow/react';
import { useWorkflowStore } from '@/stores/workflowStore';
import { useSettingsStore } from '@/stores/settingsStore';

const VIDEO_MODELS = ['seedance-2'];

export default function VideoCompositeNode({ id, data, selected }: NodeProps) {
  const d = data as unknown as NodeData;
  const cfg = d.config as { prompt?: string; model?: string; resultUrl?: string; taskId?: string };
  const { nodes, edges, updateNodeData } = useWorkflowStore();
  const { videoApi } = useSettingsStore();

  const [prompt, setPrompt] = useState(cfg.prompt ?? '');
  const [selectedModel, setSelectedModel] = useState(cfg.model ?? VIDEO_MODELS[0]);
  const [resultUrl, setResultUrl] = useState<string | null>(cfg.resultUrl ?? null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const pollRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => () => { if (pollRef.current) clearInterval(pollRef.current); }, []);

  // 从上游收集所有素材URL
  const incomingEdges = edges.filter(e => e.target === id);
  const referenceUrls: string[] = [];
  let imgUrl: string | null = null;
  let videoUrl: string | null = null;

  for (const edge of incomingEdges) {
    const sourceNode = nodes.find(n => n.id === edge.source);
    if (!sourceNode) continue;
    const sourceConfig = sourceNode.data?.config as Record<string, unknown> | undefined;
    const url = sourceConfig?.resultUrl as string | undefined;
    if (!url) continue;

    referenceUrls.push(url);
    if (edge.targetHandle === 'image') imgUrl = url;
    else if (edge.targetHandle === 'video') videoUrl = url;
  }

  const pollTask = (taskId: string) => {
    pollRef.current = setInterval(async () => {
      try {
        const resp = await fetch(
          `http://localhost:8000/api/generate/task/video/${taskId}?api_url=${encodeURIComponent(videoApi.apiUrl)}&api_key=${encodeURIComponent(videoApi.apiKey)}`
        );
        if (!resp.ok) return;
        const data = await resp.json();
        setProgress(data.progress || 0);
        if (data.status === 'completed' && data.url) {
          clearInterval(pollRef.current!);
          setResultUrl(data.url);
          setLoading(false);
          setProgress(100);
          updateNodeData(id, { config: { ...cfg, prompt, model: selectedModel, resultUrl: data.url, taskId } });
        } else if (data.status === 'failed') {
          clearInterval(pollRef.current!);
          setError(data.error || '合成失败');
          setLoading(false);
        }
      } catch {}
    }, 5000);
  };

  const handleCompose = async () => {
    if (loading) return;
    if (referenceUrls.length === 0) { setError('请连接至少一个素材节点'); return; }
    if (!prompt.trim()) { setError('请输入合成提示词，描述如何融合素材'); return; }
    if (!videoApi.apiUrl || !videoApi.apiKey) { setError('请先配置API'); return; }

    setError(null);
    setLoading(true);
    setProgress(0);

    try {
      const resp = await fetch('http://localhost:8000/api/generate/video', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt,
          api_url: videoApi.apiUrl,
          api_key: videoApi.apiKey,
          model: selectedModel,
          reference_urls: referenceUrls,
          image_url: imgUrl || undefined,
        }),
      });
      if (!resp.ok) { const e = await resp.json(); throw new Error(e.detail || '创建任务失败'); }
      const data = await resp.json();
      if (data.task_id) pollTask(data.task_id);
      else throw new Error('未返回任务ID');
    } catch (e) {
      setError(e instanceof Error ? e.message : '合成失败');
      setLoading(false);
    }
  };

  return (
    <BaseNode data={d} selected={selected} color="#a855f7">
      <div style={{ padding: '0 10px 8px' }}>
        {/* 端口标签 */}
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, marginBottom: 6 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            <span style={{ color: 'rgba(255,255,255,0.6)' }}>图片</span>
            <span style={{ background: 'rgba(59,130,246,0.2)', color: '#60a5fa', border: '1px solid rgba(59,130,246,0.3)', borderRadius: 3, padding: '0 4px', fontSize: 10 }}>IMAGE</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
            <span style={{ background: 'rgba(168,85,247,0.2)', color: '#c084fc', border: '1px solid rgba(168,85,247,0.3)', borderRadius: 3, padding: '0 4px', fontSize: 10 }}>VIDEO</span>
            <span style={{ color: 'rgba(255,255,255,0.6)' }}>输出</span>
          </div>
        </div>

        {/* 模型选择 */}
        <select
          value={selectedModel}
          onChange={e => setSelectedModel(e.target.value)}
          disabled={loading}
          style={{
            width: '100%', marginBottom: 4, fontSize: 11, color: '#d0d6e0',
            background: '#0a0a0f', border: '1px solid rgba(255,255,255,0.12)',
            borderRadius: 4, padding: '4px 6px', outline: 'none',
          }}
        >
          {VIDEO_MODELS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>

        {/* 合成提示词 */}
        <textarea
          value={prompt}
          onChange={e => setPrompt(e.target.value)}
          placeholder="描述合成要求，如：让人物手中拿着这支花..."
          onClick={e => e.stopPropagation()}
          style={{
            width: '100%', height: 40, fontSize: 11, color: '#e0e0e0',
            background: '#0a0a0f', border: `1px solid ${error ? '#ef4444' : 'rgba(255,255,255,0.12)'}`,
            borderRadius: 4, padding: '4px 6px', resize: 'none', outline: 'none',
          }}
        />

        {error && (
          <div style={{ marginTop: 3, padding: '3px 6px', background: 'rgba(239,68,68,0.1)', borderRadius: 4, border: '1px solid rgba(239,68,68,0.3)' }}>
            <p style={{ fontSize: 9, color: '#ef4444', wordBreak: 'break-all' }}>{error}</p>
          </div>
        )}

        {/* 合成按钮 */}
        <button
          onClick={handleCompose}
          disabled={loading || referenceUrls.length === 0}
          style={{
            width: '100%', marginTop: 4, fontSize: 11, fontWeight: 600, color: '#fff',
            background: loading ? 'rgba(168,85,247,0.4)' : '#a855f7',
            border: 'none', borderRadius: 4, padding: '5px 8px',
            cursor: loading || referenceUrls.length === 0 ? 'not-allowed' : 'pointer',
          }}
        >
          {loading ? `合成中 ${Math.round(progress)}%` : resultUrl ? '重新合成' : '开始合成'}
        </button>

        {loading && (
          <div style={{ marginTop: 4, height: 3, background: 'rgba(255,255,255,0.08)', borderRadius: 2, overflow: 'hidden' }}>
            <div style={{ width: `${progress}%`, height: '100%', background: '#a855f7', borderRadius: 2, transition: 'width 0.5s' }} />
          </div>
        )}

        {/* 素材预览 */}
        <div style={{ display: 'flex', gap: 4, marginTop: 4 }}>
          <div style={{ flex: 1, borderRadius: 4, overflow: 'hidden', background: '#0a0a0f', border: '1px solid rgba(255,255,255,0.08)', minHeight: 50, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {imgUrl ? (
              <img src={imgUrl} alt="图片素材" style={{ width: '100%', height: 50, objectFit: 'cover' }} />
            ) : (
              <span style={{ fontSize: 9, color: '#3a3d45' }}>图片</span>
            )}
          </div>
          <div style={{ flex: 1, borderRadius: 4, overflow: 'hidden', background: '#0a0a0f', border: '1px solid rgba(255,255,255,0.08)', minHeight: 50, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {videoUrl ? (
              <video src={videoUrl} muted style={{ width: '100%', height: 50, objectFit: 'cover' }} />
            ) : (
              <span style={{ fontSize: 9, color: '#3a3d45' }}>视频</span>
            )}
          </div>
        </div>

        {/* 合成结果 */}
        {resultUrl && (
          <div style={{ marginTop: 4 }}>
            <div style={{ borderRadius: 4, overflow: 'hidden', border: '1px solid rgba(255,255,255,0.12)' }}>
              <video src={resultUrl} controls style={{ width: '100%', height: 100, objectFit: 'cover', display: 'block' }} />
            </div>
            <a href={resultUrl} download target="_blank" rel="noopener noreferrer"
              style={{ display: 'block', width: '100%', textAlign: 'center', fontSize: 11, marginTop: 4, padding: '4px 0', borderRadius: 4, background: 'rgba(255,255,255,0.05)', color: 'rgba(255,255,255,0.6)', textDecoration: 'none' }}>
              下载合成视频
            </a>
          </div>
        )}

        {/* 状态提示 */}
        {referenceUrls.length > 0 && !resultUrl && !loading && (
          <div style={{ marginTop: 4, fontSize: 9, color: '#22c55e' }}>
            {referenceUrls.length}个素材就绪，输入提示词后开始合成
          </div>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="image"
        className="w-3 h-3 bg-blue-500 border-2 border-blue-300" style={{ left: -6, top: '40%' }} />
      <Handle type="target" position={Position.Left} id="video"
        className="w-3 h-3 bg-purple-500 border-2 border-purple-300" style={{ left: -6, top: '60%' }} />
      <Handle type="source" position={Position.Right} id="video"
        className="w-3 h-3 bg-purple-500 border-2 border-purple-300" style={{ right: -6 }} />
    </BaseNode>
  );
}
