import { useState, useRef, useEffect } from 'react';

const IMAGE_MODELS = [
  'gemini-3-pro-image-preview-official',
  'nano_banana_2',
];

export default function ImageExportNode({ id, data, selected }: NodeProps<NodeData>) {
  const { nodes, edges, updateNodeData } = useWorkflowStore();
  const { imageApi } = useSettingsStore();

  const cfg = data.config as { prompt?: string; model?: string; resultUrl?: string; taskId?: string };
  const [prompt, setPrompt] = useState(cfg.prompt ?? '');
  const [selectedModel, setSelectedModel] = useState(cfg.model ?? IMAGE_MODELS[0]);
  const [resultUrl, setResultUrl] = useState<string | null>(cfg.resultUrl ?? null);
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const pollRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => () => { if (pollRef.current) clearInterval(pollRef.current); }, []);

  // 从上游收集所有素材URL
  const incomingEdges = edges.filter(e => e.target === id);
  const referenceUrls: string[] = [];

  for (const edge of incomingEdges) {
    const sourceNode = nodes.find(n => n.id === edge.source);
    if (!sourceNode) continue;
    const sourceConfig = sourceNode.data?.config as Record<string, unknown> | undefined;
    const url = sourceConfig?.resultUrl as string | undefined;
    if (url) referenceUrls.push(url);
  }

  const pollTask = (taskId: string) => {
    pollRef.current = setInterval(async () => {
      try {
        const resp = await fetch(
          `http://localhost:8000/api/generate/task/image/${taskId}?api_url=${encodeURIComponent(imageApi.apiUrl)}&api_key=${encodeURIComponent(imageApi.apiKey)}`
        );
        if (!resp.ok) return;
        const d = await resp.json();
        setProgress(d.progress || 0);
        if (d.status === 'completed' && d.url) {
          clearInterval(pollRef.current!);
          setResultUrl(d.url);
          setLoading(false);
          setProgress(100);
          updateNodeData(id, { config: { ...cfg, prompt, model: selectedModel, resultUrl: d.url, taskId } });
        } else if (d.status === 'failed') {
          clearInterval(pollRef.current!);
          setError(d.error || '合成失败');
          setLoading(false);
        }
      } catch {}
    }, 5000);
  };

  const handleCompose = async () => {
    if (loading) return;
    if (referenceUrls.length === 0) { setError('请连接至少一个素材节点'); return; }
    if (!prompt.trim()) { setError('请输入合成提示词，描述如何融合素材'); return; }
    if (!imageApi.apiUrl || !imageApi.apiKey) { setError('请先配置API'); return; }

    setError(null);
    setLoading(true);
    setProgress(0);

    try {
      const resp = await fetch('http://localhost:8000/api/generate/image', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt,
          api_url: imageApi.apiUrl,
          api_key: imageApi.apiKey,
          model: selectedModel,
          reference_urls: referenceUrls,
        }),
      });
