{"content":"/**
 * 媒体代理工具 — 绕过CORS限制
 * toapis.com的文件服务器没有CORS头，浏览器无法直接播放
 * 通过后端代理端点获取媒体文件
 */

const PROXY_BASE = 'http://localhost:8000/api/generate/proxy';

/**
 * 将外部媒体URL转换为代理URL
 * 如果URL已经是本地的（localhost），直接返回
 */
export function proxyUrl(url: string | null): string | null {
  if (!url) return null;
  // 本地URL不需要代理
  if (url.startsWith('http://localhost') || url.startsWith('blob:') || url.startsWith('data:')) {
    return url;
  }
  // 外部URL走代理
  return `${PROXY_BASE}?url=${encodeURIComponent(url)}`;
}
